-- Petra — développé par BELEJ-CONSULTING.
-- Synchronisation station → central.
-- Chaque écriture métier ajoute une entrée dans sync_queue par déclencheur : même transaction que l'écriture,
-- et aucun module ne peut l'oublier. L'entrée ne porte que la table et l'identifiant ; bin/sync.php lit la
-- ligne au moment de l'envoi.
-- @petra_sync_apply = 1 suspend la mise en file : serveur central, ou application de données reçues.
-- @petra_station_id rattache à la station de l'installation les lignes sans station (connexions au journal).

ALTER TABLE sync_queue
    MODIFY operation ENUM('insert', 'update', 'delete') NOT NULL,
    MODIFY status ENUM('pending', 'sent', 'failed', 'conflict') NOT NULL DEFAULT 'pending';

-- Conflits : comptés et détaillés dans le journal de la passe, jamais résolus en écrasant une ligne.
ALTER TABLE sync_log
    MODIFY status ENUM('running', 'success', 'failed', 'offline') NOT NULL DEFAULT 'running',
    ADD COLUMN items_conflicted INT UNSIGNED NOT NULL DEFAULT 0 AFTER items_rejected,
    ADD COLUMN details LONGTEXT NULL AFTER error_message;
ALTER TABLE sync_log ADD CONSTRAINT chk_sl_details CHECK (details IS NULL OR JSON_VALID(details));

CREATE TRIGGER trg_products_sync_insert AFTER INSERT ON products FOR EACH ROW IF @petra_sync_apply IS NULL AND COALESCE(NEW.station_id, @petra_station_id) IS NOT NULL THEN INSERT INTO sync_queue (id, station_id, entity_type, entity_id, operation, payload) VALUES (UUID(), COALESCE(NEW.station_id, @petra_station_id), 'products', NEW.id, 'insert', '{}'); END IF;
