-- Seul le barème de jaugeage supprime des lignes (remplacement à l'import).
CREATE TRIGGER trg_tank_calibrations_sync_delete AFTER DELETE ON tank_calibrations FOR EACH ROW IF @petra_sync_apply IS NULL AND COALESCE(OLD.station_id, @petra_station_id) IS NOT NULL THEN INSERT INTO sync_queue (id, station_id, entity_type, entity_id, operation, payload) VALUES (UUID(), COALESCE(OLD.station_id, @petra_station_id), 'tank_calibrations', OLD.id, 'delete', '{}'); END IF;
